function schoolSourceLabel(s,language="en"){const year=s?.cds_year||s?.catalog_cds_year||null;const verified=s?.source_verified_at||null;const date=verified?new Date(verified).toLocaleDateString("zh-CN",{year:"numeric",month:"2-digit",day:"2-digit"}):null;const kind=s?.source_kind||((s?.data_quality||"").includes("official")?"Official source":"UniPath catalog");return {kind:language==="zh"?({"Official source":"官方来源","UniPath catalog":"UniPath 目录"}[kind]||kind):kind,year,date,url:s?.source_url||null}}
function serverChatMessage(m){const role=m.role==="assistant"?"ai":"user",clientId=m.metadata?.client_id||m.metadata?.reply_to||null;return {id:m.id||null,role,text:m.content||"",created_at:m.created_at||new Date().toISOString(),client_id:clientId,persisted:true}}
function chatIdentity(m){if(m.client_id)return `${m.role}:${m.client_id}`;if(m.id)return `id:${m.id}`;return `${m.role}:${m.text}:${String(m.created_at||"").slice(0,16)}`}
function mergeChatMessages(...groups){const map=new Map();for(const group of groups){for(const m of (group||[])){if(!m?.text)continue;map.set(chatIdentity(m),m)}}return [...map.values()].sort((a,b)=>String(a.created_at||"").localeCompare(String(b.created_at||""))).slice(-100)}

function AnalysisIndicator({language="en",kind,label}){
  const zh=language==="zh";
  const message=label||ANALYSIS_MESSAGES[kind]?.[zh?"zh":"en"]||(zh?"AI 分析中":"AI analyzing");
  return <span className="analysisIndicator" role="status" aria-live="polite"><span className="analysisDots" aria-hidden="true"><i/><i/><i/></span><span>{message}</span></span>;
}

function buildDraftPortfolio(predictions){
  const strategy=predictions?.round_strategy;
  const rows=[...(strategy?.recommended_plan||[]),...(strategy?.outside_common_app_plan||[])];
  return rows.map((p,i)=>({
    id:p.id||`model-${i}-${p.school_name}`,
    draft:true,
    school_name:p.school_name,
    program:p.program,
    major:p.major||predictions?.primary_major||null,
    round:p.round||"RD",
    probability:p.probability,
    probability_min:p.probability_min,
    probability_max:p.probability_max,
    tier:p.tier,
    status:"Planning",
    country:p.country||"us",
    rank:p.rank,
    source:p.round==="UC"?"outside_common_app":p.round==="EA"&&p.school_name==="MIT"?"outside_common_app":"model"
  }));
}

